    "bodyTemplate": "In the twilight depths of the ocean, [lumi|nous] reactions occur within specialized [li|ght] organs [cal|led] photophores. The enzymatic reaction involves the [oxid|ation] of the substrate luciferin catalyzed by the [enz|yme] luciferase. Deep-sea organisms utilize this cold light to [att|ract] potential mates, illuminate elusive [pr|ey], and confuse pursuing predators with dazzling [fla|shes] of blue-green luminescence in dark [pel|agic] [wat|ers].",
