    "topic": "Developmental Biology",
    "category": "Natural Sciences",
    "leadSentence": "Anuran amphibians undergo a dramatic morphological transformation from aquatic larvae to terrestrial adults.",
    "bodyTemplate": "The transition is governed by surges in thyroid [horm|ones] that trigger widespread tissue restructuring throughout the [tad|pole]. Aquatic [gi|lls] are systematically reabsorbed while air-breathing [lu|ngs] develop to facilitate atmospheric gas exchange. Concurrently, the swimming tail undergoes cellular apoptosis, and powerful [musc|ular] hind [li|mbs] emerge to enable terrestrial hopping on dry land. The digestive tract also [shor|tens] radically to accommodate a [carni|vorous] diet of terrestrial [ins|ects] and small [invert|ebrates].",
    "fullText": "Anuran amphibians undergo a dramatic morphological transformation from aquatic larvae to terrestrial adults. The transition is governed by surges in thyroid hormones that trigger widespread tissue restructuring throughout the tadpole. Aquatic gills are systematically reabsorbed while air-breathing lungs develop to facilitate atmospheric gas exchange. Concurrently, the swimming tail undergoes cellular apoptosis, and powerful muscular hind limbs emerge to enable terrestrial hopping on dry land. The digestive tract also shortens radically to accommodate a carnivorous diet of terrestrial insects and small invertebrates.",
