    "title": "Diatomaceous Earth and Marine Phytoplankton",
    "topic": "Micropaleontology & Ecology",
    "category": "Natural Sciences",
    "leadSentence": "Diatoms are unicellular photosynthetic microalgae encased in intricately perforated silica cell walls called frustules.",
    "bodyTemplate": "These microscopic primary [prod|ucers] [gene|rate] up to one-fifth of the atmospheric oxygen produced globally every year. When individual diatoms complete their biological [life|cycle] and die, their non-decomposable silica frustules sink through the water [col|umn] to the abyssal [sea|bed]. Over millions of years, vast [depo|sits] of this porous siliceous sediment [accum|ulate], forming extensive geological formations known as diatomaceous [ea|rth], which is utilized extensively in industrial [filtr|ation] and chemical [manufa|cturing].",
    "fullText": "Diatoms are unicellular photosynthetic microalgae encased in intricately perforated silica cell walls called frustules. These microscopic primary producers generate up to one-fifth of the atmospheric oxygen produced globally every year. When individual diatoms complete their biological lifecycle and die, their non-decomposable silica frustules sink through the water column to the abyssal seabed. Over millions of years, vast deposits of this porous siliceous sediment accumulate, forming extensive geological formations known as diatomaceous earth, which is utilized extensively in industrial filtration and chemical manufacturing.",
