    "fullText": "Dinoflagellates are marine microplankton that frequently produce dramatic bioluminescent displays in coastal waters. When mechanical shearing forces from crashing waves disturb these single-celled organisms, luciferin oxidation produces a blue flash lasting barely a fraction of a second. Under certain nutrient-rich conditions, massive population blooms occur, turning the coastal sea red or brown. Some bloom species produce potent neurotoxins that accumulate in filter-feeding shellfish, posing lethal health hazards to marine mammals and human consumers who ingest contaminated seafood during toxic algal blooms.",
