    "fullText": "Karst landscapes develop in regions where bedrock composed of soluble limestone or dolomite dissolves over geological time. Rainwater absorbs atmospheric carbon dioxide to form weak carbonic acid as it percolates through subterranean fissures. Over centuries, acidic groundwater dissolves extensive subterranean caverns. As calcium-rich water droplets seep slowly from cave ceilings, degassing releases carbon dioxide, precipitating crystalline calcium carbonate to form stalactites hanging from above and stalagmites rising from the cave floor over millennia of perpetual mineral deposition.",
