    "leadSentence": "Johannes Gutenberg's development of movable type printing around 1440 fundamentally altered European information dissemination.",
    "bodyTemplate": "Prior to [mecha|nized] printing, [manus|cripts] had to be [painst|akingly] transcribed by [mona|stic] scribes over months of labor. Gutenberg's [me|tal] alloy type and oil-based ink drastically [red|uced] the cost and [produ|ction] time required to publish books. As printed [liter|ature] became widely accessible, [lite|racy] rates expanded beyond the clerical aristocracy, fostering scientific [inq|uiry] and accelerating the religious debates of the Protestant Reformation.",
    "fullText": "Johannes Gutenberg's development of movable type printing around 1440 fundamentally altered European information dissemination. Prior to mechanized printing, manuscripts had to be painstakingly transcribed by monastic scribes over months of labor. Gutenberg's metal alloy type and oil-based ink drastically reduced the cost and production time required to publish books. As printed literature became widely accessible, literacy rates expanded beyond the clerical aristocracy, fostering scientific inquiry and accelerating the religious debates of the Protestant Reformation.",
