    "bodyTemplate": "Empirical [exper|iments] conducted by psychologists Daniel Kahneman and Amos Tversky [chall|enged] this traditional [assum|ption]. They [demons|trated] that people experience loss aversion, meaning the [psycho|logical] pain of losing a [fina|ncial] sum is roughly twice as [int|ense] as the joy of gaining the [equiv|alent] amount. Consequently, individuals exhibit [asymm|etric] risk preferences, making irrational financial choices to protect existing [ass|ets] rather than seizing advantageous speculative opportunities.",
    "fullText": "Classical economic theory assumed that human decision-makers consistently act as rational utility maximizers. Empirical experiments conducted by psychologists Daniel Kahneman and Amos Tversky challenged this traditional assumption. They demonstrated that people experience loss aversion, meaning the psychological pain of losing a financial sum is roughly twice as intense as the joy of gaining the equivalent amount. Consequently, individuals exhibit asymmetric risk preferences, making irrational financial choices to protect existing assets rather than seizing advantageous speculative opportunities.",
