    "leadSentence": "The trans-Saharan caravan trade connected West African forest kingdoms with Mediterranean mercantile networks.",
    "bodyTemplate": "Berber [tra|ders] utilized camel [cara|vans] [cap|able] of [trave|rsing] waterless sand seas for weeks without [replen|ishment]. Gold mined in the [sava|nnah] regions of Ghana and Mali was traded directly for Saharan rock salt, an [indisp|ensable] dietary [preser|vative] in tropical climates. This [lucr|ative] overland commerce fostered powerful West African commercial [emp|ires], stimulated urban scholarship in centers like Timbuktu, and facilitated the spread of Islamic literacy across the Sahel.",
