    "leadSentence": "The Black Death pandemic of 1347 eliminated between thirty and sixty percent of the European human population.",
    "bodyTemplate": "The sudden [demog|raphic] catastrophe generated severe labor [shor|tages] across rural [mano|rial] estates. With fertile cropland sitting [unhar|vested], surviving serfs possessed unprecedented economic [barga|ining] leverage against aristocratic [land|lords]. Peasant laborers [dema|nded] higher cash wages and resisted feudal servitude, prompting [lando|wners] to transition from labor-intensive crop cultivation to sheep [pasto|ralism]. This socioeconomic disruption [weak|ened] feudalism and accelerated the growth of cash-based rural economies.",
    "fullText": "The Black Death pandemic of 1347 eliminated between thirty and sixty percent of the European human population. The sudden demographic catastrophe generated severe labor shortages across rural manorial estates. With fertile cropland sitting unharvested, surviving serfs possessed unprecedented economic bargaining leverage against aristocratic landlords. Peasant laborers demanded higher cash wages and resisted feudal servitude, prompting landowners to transition from labor-intensive crop cultivation to sheep pastoralism. This socioeconomic disruption weakened feudalism and accelerated the growth of cash-based rural economies.",
