    "topic": "Macroeconomics & Banking History",
    "category": "Social Sciences",
    "leadSentence": "The evolution of central banking transformed national monetary systems from commodity-backed currencies to legal tender fiat money.",
    "bodyTemplate": "Early central banks such as the Bank of England originally issued paper [bank|notes] [redee|mable] on demand for [phys|ical] gold or silver specie. Over time, [fract|ional] reserve practices allowed banks to issue notes [exce|eding] their vault reserves to finance state [expend|itures] and stabilize commercial [pan|ics]. In the twentieth century, governments [sev|ered] the statutory gold link entirely, establishing unbacked fiat currency whose value derives strictly from [sove|reign] legal decree and public [instit|utional] trust.",
    "fullText": "The evolution of central banking transformed national monetary systems from commodity-backed currencies to legal tender fiat money. Early central banks such as the Bank of England originally issued paper banknotes redeemable on demand for physical gold or silver specie. Over time, fractional reserve practices allowed banks to issue notes exceeding their vault reserves to finance state expenditures and stabilize commercial panics. In the twentieth century, governments severed the statutory gold link entirely, establishing unbacked fiat currency whose value derives strictly from sovereign legal decree and public institutional trust.",
