    "topic": "Classical Economics",
    "category": "Social Sciences",
    "leadSentence": "Adam Smith famously analyzed the economic principles of the division of labor in his seminal 1776 work, The Wealth of Nations.",
    "bodyTemplate": "Smith demonstrated that [subdi|viding] complex manufacturing tasks into narrow, [repet|itive] operations drastically multiplies overall [produc|tivity]. Using the example of a pin factory, he observed that ten [speci|alized] workers performing dedicated steps could produce tens of thousands of pins daily, whereas an individual [art|isan] working alone could barely [fabr|icate] twenty. [Special|ization] eliminates the time lost [transi|tioning] between disparate tasks, stimulates [mecha|nical] invention, and expands [aggr|egate] market output.",
    "fullText": "Adam Smith famously analyzed the economic principles of the division of labor in his seminal 1776 work, The Wealth of Nations. Smith demonstrated that subdividing complex manufacturing tasks into narrow, repetitive operations drastically multiplies overall productivity. Using the example of a pin factory, he observed that ten specialized workers performing dedicated steps could produce tens of thousands of pins daily, whereas an individual artisan working alone could barely fabricate twenty. Specialization eliminates the time lost transitioning between disparate tasks, stimulates mechanical invention, and expands aggregate market output.",
