    "title": "Gothic Architecture and Flying Buttresses",
    "topic": "Medieval Architecture",
    "category": "Arts & Humanities",
    "leadSentence": "High Gothic cathedrals achieved unprecedented verticality and luminosity through revolutionary structural engineering innovations.",
    "bodyTemplate": "Earlier Romanesque churches relied on massive stone walls to support heavy masonry [bar|rel] vaults, resulting in dark, fortress-like [inte|riors]. Gothic master masons [dev|ised] external flying buttresses that redirected the [lat|eral] thrust of towering vaults away from walls to exterior [pi|ers]. [Reli|eved] of [compr|essive] structural loads, the exterior walls could be dissolved into [expa|nsive] traceried armatures filled with brilliant [sta|ined] glass that bathed cathedral naves in colored [div|ine] light.",
    "fullText": "High Gothic cathedrals achieved unprecedented verticality and luminosity through revolutionary structural engineering innovations. Earlier Romanesque churches relied on massive stone walls to support heavy masonry barrel vaults, resulting in dark, fortress-like interiors. Gothic master masons devised external flying buttresses that redirected the lateral thrust of towering vaults away from walls to exterior piers. Relieved of compressive structural loads, the exterior walls could be dissolved into expansive traceried armatures filled with brilliant stained glass that bathed cathedral naves in colored divine light.",
