    "leadSentence": "Ukiyo-e, or pictures of the floating world, flourished as a popular art genre in Edo-period Japan.",
    "bodyTemplate": "Creating multicolor [polyc|hrome] prints required meticulous [collab|oration] between publisher, master [illus|trator], carver, and printer. Specialist craftsmen carved the reverse design into fine-grained mountain [che|rry] wood blocks, carving [dist|inct] plates for each separate pigment color. Printers brushed water-based [vege|table] inks and rice paste onto woodblocks before [rub|bing] handmade [mulb|erry] paper with a circular baren, mass-producing affordable graphic masterpieces depicting actors, [court|esans], and natural [lands|capes].",
