    "title": "The Epic of Gilgamesh and Ancient Flood Myths",
    "topic": "Comparative Literature & Mythology",
    "category": "Arts & Humanities",
    "leadSentence": "The Epic of Gilgamesh is widely recognized as one of humankind's earliest surviving masterpieces of heroic literature.",
    "bodyTemplate": "Originating in ancient Sumer and preserved on twelve royal clay [tab|lets] in Nineveh, the epic [reco|unts] the existential [jou|rney] of the historical king of Uruk. Devastated by the [tra|gic] [mort|ality] of his companion Enkidu, Gilgamesh ventures beyond the cosmic waters to seek [immor|tality] from Utnapishtim, the legendary sole [surv|ivor] of an ancient catastrophic [del|uge]. The narrative explores universal human [anxi|eties] concerning physical mortality, fragile hubris, and the [endu|ring] quest for enduring cultural legacy.",
    "fullText": "The Epic of Gilgamesh is widely recognized as one of humankind's earliest surviving masterpieces of heroic literature. Originating in ancient Sumer and preserved on twelve royal clay tablets in Nineveh, the epic recounts the existential journey of the historical king of Uruk. Devastated by the tragic mortality of his companion Enkidu, Gilgamesh ventures beyond the cosmic waters to seek immortality from Utnapishtim, the legendary sole survivor of an ancient catastrophic deluge. The narrative explores universal human anxieties concerning physical mortality, fragile hubris, and the enduring quest for enduring cultural legacy.",
