    "fullText": "Buon fresco was considered the most prestigious and technically demanding mural painting technique of the Italian Renaissance. Masters applied ground mineral pigments mixed with water directly onto freshly laid, moist lime plaster called the intonaco. As the wet plaster cured over hours, a chemical reaction carbonated the lime, permanently binding the pigment particles into the crystalline masonry wall. Artists had to work with rapid certainty on small daily sections known as giornate before the plaster dried, as subsequent alterations required completely chiseling away the hardened mortar.",
