    "fullText": "Founded by Walter Gropius in 1919, the German Bauhaus school revolutionized modern architecture and product design. The Bauhaus philosophy sought to bridge the historical divide between fine art and industrial manufacturing under the maxim that form follows function. Faculty rejected nineteenth-century ornamental embellishments in favor of clean geometric forms, steel tubing, and unadorned reinforced concrete. By collaborating with industrial factories, Bauhaus designers created elegant, functional household furnishings and modular architecture intended to be mass-produced for the democratic benefit of working people.",
