    "fullText": "The transition from Romanesque to Gothic architecture hinged on fundamental innovations in ceiling vault engineering. Romanesque barrel vaults exerted continuous outward lateral thrust along entire masonry walls, requiring massive perimeter walls with few windows. In contrast, the invention of intersecting diagonal ribbed vaults concentrated structural downward loads onto specific reinforced corner piers. This concentrated load distribution permitted the intermediate wall spans to be opened up for monumental stained glass windows, transforming dim medieval basilicas into luminous ecclesiastical sanctuaries.",
