    "fullText": "Italian Baroque painter Caravaggio revolutionized visual storytelling through his intense deployment of dramatic chiaroscuro. Abandoning the balanced, idealized illumination of High Renaissance painting, Caravaggio developed tenebrism, an extreme contrast between blinding highlight and impenetrable black shadow. He positioned unidealized biblical figures within pitch-dark backgrounds, illuminated by a single harsh theatrical beam of directional light. This stark visual polarization emphasized raw psychological tension, highlighted physical flesh imperfections, and thrust the spiritual drama directly into the viewer's immediate physical space.",
