    "fullText": "Early twentieth-century modernist novelists fractured traditional linear narration to capture the authentic flow of human consciousness. Pioneering authors such as Virginia Woolf and James Joyce rejected omniscient third-person plot structures. Instead, they employed stream of consciousness techniques, tracing the chaotic, unfiltered sequence of sensory perceptions, memories, and fleeting subconscious associations passing through a protagonist's mind. By subverting chronological chronology and conventional syntactical punctuation, these novels mirrored the fragmented psychological reality of individuals navigating modern industrial urban alienation.",
