    "title": "Romanticism and the Aesthetic of the Sublime",
    "topic": "Art History & Philosophy",
    "category": "Arts & Humanities",
    "leadSentence": "The late eighteenth-century Romantic movement reacted against the cold rationalism of the Enlightenment by exalting intense emotion.",
    "bodyTemplate": "Central to Romantic landscape painting was the philosophical [con|cept] of the sublime, defined by Edmund Burke as awe [min|gled] with [ter|ror]. Painters such as Caspar David Friedrich and J.M.W. Turner depicted puny human [trav|elers] [dwa|rfed] by raging oceanic storms, impassable [alp|ine] precipices, and volcanic [erup|tions]. These dramatic scenes aimed to evoke [humi|lity], reminding viewers of humanity's [insigni|ficance] when confronting the unfathomable, untamed majesty of natural [primo|rdial] forces.",
    "fullText": "The late eighteenth-century Romantic movement reacted against the cold rationalism of the Enlightenment by exalting intense emotion. Central to Romantic landscape painting was the philosophical concept of the sublime, defined by Edmund Burke as awe mingled with terror. Painters such as Caspar David Friedrich and J.M.W. Turner depicted puny human travelers dwarfed by raging oceanic storms, impassable alpine precipices, and volcanic eruptions. These dramatic scenes aimed to evoke humility, reminding viewers of humanity's insignificance when confronting the unfathomable, untamed majesty of natural primordial forces.",
