    "leadSentence": "Traditional African ceremonial masks exerted a profound catalytic influence on the development of early twentieth-century Western modern art.",
    "bodyTemplate": "When Pablo Picasso visited the Trocadéro Ethnographic Museum in Paris in 1907, he was [trans|fixed] by wooden [sculp|tural] masks from western Africa. Rather than mimicking [anato|mical] realism, African sculptors [abstr|acted] facial features into bold [pla|nar] geometries, geometric eye cylinders, and stylized [ang|ular] planes. Inspired by this conceptual expressive [fre|edom], Picasso [disma|ntled] classical single-point perspective, synthesizing multiple simultaneous [viewp|oints] to create the [revolu|tionary] visual language of Cubism.",
    "fullText": "Traditional African ceremonial masks exerted a profound catalytic influence on the development of early twentieth-century Western modern art. When Pablo Picasso visited the Trocadéro Ethnographic Museum in Paris in 1907, he was transfixed by wooden sculptural masks from western Africa. Rather than mimicking anatomical realism, African sculptors abstracted facial features into bold planar geometries, geometric eye cylinders, and stylized angular planes. Inspired by this conceptual expressive freedom, Picasso dismantled classical single-point perspective, synthesizing multiple simultaneous viewpoints to create the revolutionary visual language of Cubism.",
