    "leadSentence": "In medieval theology, light was celebrated as the physical manifestation of divine spiritual wisdom.",
    "bodyTemplate": "Abbot Suger of Saint-Denis spearheaded the [archit|ectural] shift that incorporated expansive stained glass [clere|story] windows into church choirs. [Craf|tsmen] added [meta|llic] salts including cobalt and gold oxide to molten glass pots to produce [satu|rated] blues and rubies. When sunlight [penet|rated] these vibrant narrative window panels, the [filt|ered] light became lux nova, an [ethe|real] illumination intended to transport [worsh|ippers] from material worldly concerns to contemplative contemplation of celestial [divi|nity].",
