    "bodyTemplate": "Literati [scho|lars] practiced calligraphy using the Four Treasures of the Study: inkstone, inkstick, animal-hair brush, and handmade xuan paper. By [grin|ding] the solid pine-soot inkstick in fresh water upon the slate stone, the calligrapher controlled ink [satur|ation] and [visc|osity]. The [flex|ible] animal-hair brush allowed immediate variation in stroke [thic|kness], dynamic pressure, and [rhyt|hmic] speed, transforming written Chinese [chara|cters] into spontaneous musical [choreo|graphy] reflecting the scholar's inner spiritual [culti|vation].",
    "fullText": "In imperial China, calligraphy was revered above painting as the supreme visual art form embodying moral character. Literati scholars practiced calligraphy using the Four Treasures of the Study: inkstone, inkstick, animal-hair brush, and handmade xuan paper. By grinding the solid pine-soot inkstick in fresh water upon the slate stone, the calligrapher controlled ink saturation and viscosity. The flexible animal-hair brush allowed immediate variation in stroke thickness, dynamic pressure, and rhythmic speed, transforming written Chinese characters into spontaneous musical choreography reflecting the scholar's inner spiritual cultivation.",
