    "fullText": "Vernacular architecture refers to regional building traditions constructed by local people using native materials without professional architects. These traditional dwellings evolved over centuries to provide optimal passive thermal comfort in response to specific local microclimates. In hot arid regions, adobe houses feature thick earthen mud-brick walls with high thermal mass, absorbing daytime solar heat and radiating warmth inward during chilly desert nights. Similarly, stilt houses in tropical monsoon zones utilize elevated bamboo platforms and steeply pitched thatched roofs to promote cross-ventilation and prevent seasonal monsoon flood inundation.",
