    "topic": "Biotechnology & Genetics",
    "category": "Applied Technology",
    "leadSentence": "The CRISPR-Cas9 system revolutionized biotechnology by enabling targeted molecular editing of living genomes.",
    "bodyTemplate": "Adapted from natural [bact|erial] immune defenses against [inva|ding] viruses, the molecular system utilizes [synt|hetic] guide RNA to identify matching nucleotide [sequ|ences] within cellular DNA. Once the target sequence is [loc|ated], the Cas9 endonuclease enzyme acts like molecular [scis|sors], [cut|ting] both strands of the double helix at a precise locus. Cellular DNA repair [mecha|nisms] then insert or delete specific gene [frag|ments], permitting geneticists to correct hereditary disease [muta|tions].",
    "fullText": "The CRISPR-Cas9 system revolutionized biotechnology by enabling targeted molecular editing of living genomes. Adapted from natural bacterial immune defenses against invading viruses, the molecular system utilizes synthetic guide RNA to identify matching nucleotide sequences within cellular DNA. Once the target sequence is located, the Cas9 endonuclease enzyme acts like molecular scissors, cutting both strands of the double helix at a precise locus. Cellular DNA repair mechanisms then insert or delete specific gene fragments, permitting geneticists to correct hereditary disease mutations.",
