    "leadSentence": "Asymmetric public-key cryptography provides the foundational security architecture for digital communications across the internet.",
    "bodyTemplate": "Unlike symmetric cryptographic [sch|emes] that require communicating parties to share a [confid|ential] private secret key in advance, public-key [algor|ithms] utilize mathematically paired [asymm|etric] keys. A public key [encr|ypts] outgoing messages and is [publ|ished] openly, while a corresponding private key held securely by the [reci|pient] decrypts the ciphertext. The mathematical security of algorithms like RSA relies on the [comput|ational] difficulty of [fact|oring] massive prime numbers into their original prime [compo|nents].",
    "fullText": "Asymmetric public-key cryptography provides the foundational security architecture for digital communications across the internet. Unlike symmetric cryptographic schemes that require communicating parties to share a confidential private secret key in advance, public-key algorithms utilize mathematically paired asymmetric keys. A public key encrypts outgoing messages and is published openly, while a corresponding private key held securely by the recipient decrypts the ciphertext. The mathematical security of algorithms like RSA relies on the computational difficulty of factoring massive prime numbers into their original prime components.",
