    "leadSentence": "Messenger RNA vaccine technology represents a breakthrough platform in modern preventative medicine.",
    "bodyTemplate": "Synthetic messenger RNA instructs host human cells to [trans|iently] produce viral spike [anti|gens] that stimulate protective [neutra|lizing] antibody production without exposing the recipient to live [path|ogens]. Because fragile naked RNA molecules would rapidly [deg|rade] in physiological [flu|ids], genetic instructions are [encaps|ulated] within synthetic lipid nanoparticles. These microscopic fatty [sph|eres] shield genetic material during [intram|uscular] injection and facilitate fusion with cellular membranes to deliver instructions directly into human [cyto|plasm].",
