    "leadSentence": "Geothermal heat pump systems exploit the relatively constant subterranean temperature of the shallow Earth.",
    "bodyTemplate": "A few meters beneath the soil surface, ground temperatures remain [sta|ble] year-round regardless of extreme seasonal atmospheric weather [fluctu|ations]. In heating mode, [close|dloop] pipes filled with circulating [antif|reeze] fluid absorb subterranean [war|mth] and deliver it to an indoor [compr|essor] that concentrates the heat for building spaces. In summer, the [refrig|eration] thermodynamic cycle [reve|rses], [extra|cting] excess thermal heat from warm indoor air and [reje|cting] it back into the cool earth.",
    "fullText": "Geothermal heat pump systems exploit the relatively constant subterranean temperature of the shallow Earth. A few meters beneath the soil surface, ground temperatures remain stable year-round regardless of extreme seasonal atmospheric weather fluctuations. In heating mode, closed-loop pipes filled with circulating antifreeze fluid absorb subterranean warmth and deliver it to an indoor compressor that concentrates the heat for building spaces. In summer, the refrigeration thermodynamic cycle reverses, extracting excess thermal heat from warm indoor air and rejecting it back into the cool earth.",
