    "topic": "Telecommunications Engineering",
    "category": "Applied Technology",
    "leadSentence": "Modern global telecommunication networks transmit trillions of data bits per second through optical fiber cables.",
    "bodyTemplate": "Data is converted into [modu|lated] light pulses produced by solid-state semiconductor laser [dio|des]. These light signals [prop|agate] through ultra-pure silica glass cores via total internal [refle|ction]. Because the surrounding glass [clad|ding] possesses a lower [refra|ctive] index than the core, light rays striking the core [boun|dary] at shallow angles bounce back without [esca|ping] outward. This guiding mechanism enables high-bandwidth, low-[atten|uation] signal transmission across transoceanic [unde|rsea] cables spanning thousands of kilometers.",
    "fullText": "Modern global telecommunication networks transmit trillions of data bits per second through optical fiber cables. Data is converted into modulated light pulses produced by solid-state semiconductor laser diodes. These light signals propagate through ultra-pure silica glass cores via total internal reflection. Because the surrounding glass cladding possesses a lower refractive index than the core, light rays striking the core boundary at shallow angles bounce back without escaping outward. This guiding mechanism enables high-bandwidth, low-attenuation signal transmission across transoceanic undersea cables spanning thousands of kilometers.",
