    "topic": "Civil & Environmental Engineering",
    "category": "Applied Technology",
    "leadSentence": "Municipal wastewater treatment facilities process millions of gallons of sewage daily to protect freshwater watersheds.",
    "bodyTemplate": "In [seco|ndary] biological treatment, settled wastewater enters massive [aera|tion] basins where [compr|essors] bubble oxygen through the liquid effluent. This [diss|olved] oxygen feeds a dense community of aerobic [microor|ganisms], including bacteria, protozoa, and rotifers, collectively known as [acti|vated] [slu|dge]. These microbes consume dissolved organic [pollu|tants] and assimilate suspended nutrients before wastewater moves to secondary [clari|fiers] where microbial flocs settle out by gravity, leaving clean treated water for ecological [disc|harge].",
    "fullText": "Municipal wastewater treatment facilities process millions of gallons of sewage daily to protect freshwater watersheds. In secondary biological treatment, settled wastewater enters massive aeration basins where compressors bubble oxygen through the liquid effluent. This dissolved oxygen feeds a dense community of aerobic microorganisms, including bacteria, protozoa, and rotifers, collectively known as activated sludge. These microbes consume dissolved organic pollutants and assimilate suspended nutrients before wastewater moves to secondary clarifiers where microbial flocs settle out by gravity, leaving clean treated water for ecological discharge.",
