    "id": "ctw_90",
    "title": "Magnetic Resonance Imaging (MRI) and Proton Spin",
    "topic": "Biomedical Imaging & Physics",
    "category": "Applied Technology",
    "leadSentence": "Magnetic Resonance Imaging produces non-invasive, high-contrast anatomical cross-sections of soft human tissues.",
    "bodyTemplate": "The patient is placed within a powerful [superco|nducting] magnetic bore that aligns the magnetic moments of hydrogen [pro|tons] [abund|antly] present in bodily water molecules. A radiofrequency [trans|mitter] pulse is then emitted, [defle|cting] proton spins out of [equil|ibrium] alignment. When the radiofrequency pulse [termi|nates], [rela|xing] protons re-align with the static magnetic field, emitting faint radio signals detected by localized [rece|iver] coils that specialized software reconstructs into detailed [diagn|ostic] cross-sectional images.",
    "fullText": "Magnetic Resonance Imaging produces non-invasive, high-contrast anatomical cross-sections of soft human tissues. The patient is placed within a powerful superconducting magnetic bore that aligns the magnetic moments of hydrogen protons abundantly present in bodily water molecules. A radiofrequency transmitter pulse is then emitted, deflecting proton spins out of equilibrium alignment. When the radiofrequency pulse terminates, relaxing protons re-align with the static magnetic field, emitting faint radio signals detected by localized receiver coils that specialized software reconstructs into detailed diagnostic cross-sectional images.",
